"""Encoded prompt strings for chat router (build-time obfuscation)."""
import base64 as _b64

_K = bytes.fromhex('e521f58cd873ca6215ef5f0ea0b4d4342f2361aa4db06c31908e6d4afd7c76b8')

def _d(s: str) -> str:
    raw = _b64.b64decode(s)
    return bytes(b ^ _K[i % len(_K)] for i, b in enumerate(raw)).decode("utf-8")

_E = {
    "p1": "",
    "p2": "",
    "p3": "",
    "p4": "",
    "p5": "",
    "p6": "",
}

def P(name: str) -> str:
    return _d(_E[name])
